import os, glob, random
import cv2
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader, random_split
import albumentations as A

# -----------------------------
# Paths
# -----------------------------
BASE = "/content/drive/MyDrive/BRISC/brisc2025/segmentation_task"
TRAIN_IMG_DIR = os.path.join(BASE, "train", "images")
TRAIN_MASK_DIR = os.path.join(BASE, "train", "masks")

IMG_EXT = ".jpg"
MASK_EXT = ".png"

# -----------------------------
# Matching pairs
# -----------------------------
train_imgs = sorted(glob.glob(os.path.join(TRAIN_IMG_DIR, f"*{IMG_EXT}")))
train_masks = sorted(glob.glob(os.path.join(TRAIN_MASK_DIR, f"*{MASK_EXT}")))
mask_dict = {os.path.basename(m).replace(MASK_EXT,""): m for m in train_masks}

pairs = []
for im in train_imgs:
    key = os.path.basename(im).replace(IMG_EXT,"")
    if key in mask_dict:
        pairs.append((im, mask_dict[key]))

print(f"Total matching pairs: {len(pairs)}")

# -----------------------------
# Augmentation + Preprocessing
# -----------------------------
transform = A.Compose([
    A.Resize(256, 256),
    A.HorizontalFlip(p=0.5),
    A.VerticalFlip(p=0.5),
    A.RandomRotate90(p=0.5),
    A.ShiftScaleRotate(shift_limit=0.05, scale_limit=0.1, rotate_limit=15, p=0.5),
])

class BriscSegDataset(Dataset):
    def __init__(self, pairs, transform=None):
        self.pairs = pairs
        self.transform = transform
    def __len__(self):
        return len(self.pairs)
    def __getitem__(self, idx):
        im_path, m_path = self.pairs[idx]
        img = cv2.imread(im_path, cv2.IMREAD_GRAYSCALE).astype(np.float32)
        mask = cv2.imread(m_path, cv2.IMREAD_GRAYSCALE)
        # Normalize
        img = (img - img.min()) / (img.max() - img.min() + 1e-9)
        mask = (mask > 127).astype(np.float32)
        # Augmentation
        if self.transform:
            augmented = self.transform(image=img, mask=mask)
            img = augmented['image']
            mask = augmented['mask']
        img = np.expand_dims(img,0)  # 1xHxW
        mask = np.expand_dims(mask,0)
        return torch.tensor(img, dtype=torch.float32), torch.tensor(mask, dtype=torch.float32)

# -----------------------------
# Train-Validation Split
# -----------------------------
dataset = BriscSegDataset(pairs, transform=transform)
val_size = int(0.1 * len(dataset))  # 10% validation
train_size = len(dataset) - val_size
train_dataset, val_dataset = random_split(dataset, [train_size, val_size])

train_loader = DataLoader(train_dataset, batch_size=4, shuffle=True)
val_loader = DataLoader(val_dataset, batch_size=4, shuffle=False)

