# --- ৩. Data Pairing ---
def get_data_pairs(base_path, img_ext, mask_ext):
    TRAIN_IMG_DIR = Path(base_path) / "train" / "images"
    TRAIN_MASK_DIR = Path(base_path) / "train" / "masks"

    if not TRAIN_IMG_DIR.exists() or not TRAIN_MASK_DIR.exists():
        print(f"Error: Training directories not found at: {TRAIN_IMG_DIR}")
        return []

    train_imgs = list(TRAIN_IMG_DIR.glob(f"*{img_ext}"))
    train_masks = list(TRAIN_MASK_DIR.glob(f"*{mask_ext}"))

    mask_dict = {}
    for m in train_masks:
        stem = m.stem
        if '_mask' in stem:
            image_base_name = stem.replace("_mask", "")
        elif '_seg' in stem:
            image_base_name = stem.replace("_seg", "")
        else:
            image_base_name = stem
        mask_dict[image_base_name] = m

    pairs = []
    removed_count = 0
    for im_path in train_imgs:
        image_base_name = im_path.stem
        if image_base_name in mask_dict:
            pairs.append((str(im_path), str(mask_dict[image_base_name])))
        else:
            removed_count += 1

    print(f"Total Images: {len(train_imgs)}, Masks: {len(train_masks)}, Matched: {len(pairs)}, Removed: {removed_count}")
    return pairs

PAIRS = get_data_pairs(BASE, IMG_EXT, MASK_EXT)
