# --- ৪. Custom Dataset (Noise Fix Applied) ---
class TumorSegmentationDataset(Dataset):
    def __init__(self, pairs, augmentation=None):
        self.pairs = pairs
        self.augmentation = augmentation
    def __len__(self):
        return len(self.pairs)
    def __getitem__(self, idx):
        img_path, mask_path = self.pairs[idx]

        # Image Loading Fix (Ensures 3 channels and correct color space)
        image = cv2.imread(img_path, cv2.IMREAD_COLOR)
        image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)

        mask = cv2.imread(mask_path, cv2.IMREAD_GRAYSCALE)
        if mask is None:
            mask = np.zeros((IMAGE_SIZE, IMAGE_SIZE), dtype=np.float32)
        else:
            mask = np.where(mask>0,1.0,0.0).astype(np.float32)

        if image.ndim==2:
            image = cv2.cvtColor(image, cv2.COLOR_GRAY2RGB)

        if self.augmentation:
            sample = self.augmentation(image=image, mask=mask)
            image, mask = sample['image'], sample['mask']

        # Pytorch format: CHW
        image = np.transpose(image, (2,0,1))
        mask = np.expand_dims(mask, axis=0)

        return torch.tensor(image,dtype=torch.float32), torch.tensor(mask,dtype=torch.float32)

# --- ৫. Augmentations & Dataloaders ---
