# 🚨 CRITICAL FIX: Combined Dice + Focal Loss (FocalLoss does not take 'from_logits')
class CombinedDiceFocalLoss(nn.Module):
    def __init__(self, dice_weight=0.5, focal_weight=0.5, gamma=2.0):
        super().__init__()

        # Dice Loss handles logits correctly
        self.dice = smp.losses.DiceLoss(mode='binary', from_logits=True)

        # Focal Loss does NOT take from_logits. We must apply sigmoid manually in forward pass.
        self.focal = smp.losses.FocalLoss(mode='binary', gamma=gamma)

        self.dice_weight = dice_weight
        self.focal_weight = focal_weight

    def forward(self, pred, target):
        # Dice Loss is calculated on raw logits
        loss_dice = self.dice(pred, target)

        # Focal Loss requires probability output (0-1), so apply sigmoid to logits
        pred_prob = torch.sigmoid(pred)
        loss_focal = self.focal(pred_prob, target)

        return self.dice_weight * loss_dice + self.focal_weight * loss_focal

criterion = CombinedDiceFocalLoss()
print("✅ Loss Setup: Combined Dice (from_logits=True) + Focal (Sigmoid Applied Manually) Loss ব্যবহার করা হয়েছে।")

optimizer = optim.AdamW(model.parameters(), lr=LEARNING_RATE)
scheduler = ReduceLROnPlateau(optimizer, mode='min', factor=0.5, patience=5)

# Metrics (Calculated on binary mask)
dice_metric = smp.losses.DiceLoss(mode='binary', from_logits=False)
iou_metric = smp.losses.JaccardLoss(mode='binary', from_logits=False)
LOGITS_CHECK_TRIGGERED=False

def calculate_metrics(y_pred_logits, y_true):
    global LOGITS_CHECK_TRIGGERED
    if not LOGITS_CHECK_TRIGGERED:
        print(f"\n[LOGITS CHECK] Min:{y_pred_logits.min().item():.4f}, Max:{y_pred_logits.max().item():.4f}, Mean:{y_pred_logits.mean().item():.4f}")
        LOGITS_CHECK_TRIGGERED=True

    y_pred_binary = (torch.sigmoid(y_pred_logits)>0.5).float()

    # Calculate scores (1.0 - Loss)
    dice_score = 1.0 - dice_metric(y_pred_binary, y_true).item()
    iou_score = 1.0 - iou_metric(y_pred_binary, y_true).item()

    return dice_score, iou_score

# --- ৭. Training & Validation Functions (Updated AMP API) ---
def train_one_epoch(model,dataloader,criterion,optimizer,device):
    model.train(); total_loss=0; total_dice=0; total_iou=0
    n = len(dataloader.dataset)
    scaler = torch.amp.GradScaler(enabled=(device.type=="cuda"))
    for imgs,masks in tqdm(dataloader,desc="Training"):
        imgs, masks = imgs.to(device), masks.to(device)
        optimizer.zero_grad()
        with torch.amp.autocast(device_type='cuda', enabled=(device.type=="cuda")):
            outputs = model(imgs)
            loss = criterion(outputs, masks)
        scaler.scale(loss).backward()
        scaler.step(optimizer)
        scaler.update()
        total_loss += loss.item()*imgs.size(0)
        d,i = calculate_metrics(outputs, masks)
        total_dice += d*imgs.size(0)
        total_iou += i*imgs.size(0)
    return total_loss/n, total_dice/n, total_iou/n

@torch.no_grad()
def validate(model,dataloader,criterion,device):
    model.eval(); total_loss=0; total_dice=0; total_iou=0
    n = len(dataloader.dataset)
    for imgs,masks in tqdm(dataloader,desc="Validation"):
        imgs, masks = imgs.to(device), masks.to(device)
        with torch.amp.autocast(device_type='cuda', enabled=(device.type=="cuda")):
            outputs = model(imgs)
            loss = criterion(outputs, masks)
        total_loss += loss.item()*imgs.size(0)
        d,i = calculate_metrics(outputs, masks)
        total_dice += d*imgs.size(0)
        total_iou += i*imgs.size(0)
    return total_loss/n, total_dice/n, total_iou/n

# --- ৮. Training Loop (Model Loading Added) ---
best_dice=0
history={'train_loss':[],'val_loss':[],'train_dice':[],'val_dice':[],'train_iou':[],'val_iou':[]}
Path("/content/drive/MyDrive/BRISC").mkdir(parents=True, exist_ok=True)

# Model Loading/Resume check
if os.path.exists(SAVE_PATH):
    print(f"✅ Loading saved weights for resume/test from: {SAVE_PATH}")
    try:
        model.load_state_dict(torch.load(SAVE_PATH, map_location=DEVICE))
        print("Model weights successfully loaded.")
    except Exception as e:
        print(f"Error loading model weights: {e}. Starting from scratch.")
else:
    print("No saved weights found. Starting training from Epoch 1.")


for epoch in range(MAX_EPOCHS):
    global LOGITS_CHECK_TRIGGERED; LOGITS_CHECK_TRIGGERED=False
    print(f"\n--- Epoch {epoch+1}/{MAX_EPOCHS} (LR:{optimizer.param_groups[0]['lr']:.6f}) ---")
    train_loss, train_dice, train_iou = train_one_epoch(model, train_loader, criterion, optimizer, DEVICE)
    val_loss, val_dice, val_iou = validate(model, val_loader, criterion, DEVICE)
    scheduler.step(val_loss)
    history['train_loss'].append(train_loss); history['val_loss'].append(val_loss)
    history['train_dice'].append(train_dice); history['val_dice'].append(val_dice)
    history['train_iou'].append(train_iou); history['val_iou'].append(val_iou)
    print(f"Train Loss:{train_loss:.4f} | Dice:{train_dice:.4f} | IoU:{train_iou:.4f}")
    print(f"Val   Loss:{val_loss:.4f} | Dice:{val_dice:.4f} | IoU:{val_iou:.4f}")
    if val_dice>best_dice:
        best_dice=val_dice
        torch.save(model.state_dict(), SAVE_PATH)
        print(f"✅ Model Saved! New Best Dice: {best_dice:.4f}")

print(f"\n--- TRAINING COMPLETE (Test Run) --- Best Validation Dice: {best_dice:.4f}")

# --- ৯. Plotting ---
def plot_history(history):
    epochs=range(1,len(history['train_loss'])+1)
    plt.figure(figsize=(18,6))
    plt.subplot(1,3,1)
    plt.plot(epochs,history['train_loss'],'b-',label='Train Loss')
