# --- ২. CONFIGURATION ---
BASE = "/content/drive/MyDrive/BRISC/brisc2025/segmentation_task"
IMG_EXT = ".jpg"
MASK_EXT = ".png"

DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
BATCH_SIZE = 12
IMAGE_SIZE = 256
