import cv2
import segmentation_models_pytorch as smp
import albumentations as A
from pathlib import Path
import matplotlib.pyplot as plt
from tqdm.autonotebook import tqdm
import random
import os

# --- ২. CONFIGURATION ---
BASE = "/content/drive/MyDrive/BRISC/brisc2025/segmentation_task"
IMG_EXT = ".jpg"
MASK_EXT = ".png"
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
BATCH_SIZE = 12
IMAGE_SIZE = 256
SAVE_PATH = "/content/drive/MyDrive/BRISC/best_deeplabv3plus_efficientnetb3_focal_test.pth"
SIMPLE_MEAN = [0.5,0.5,0.5]
SIMPLE_STD = [0.5,0.5,0.5]

# --- ৩. Data Pairing (Test) ---
def get_data_pairs(base_path, img_ext, mask_ext, split="test"):
    IMG_DIR = Path(base_path)/split/"images"
    MASK_DIR = Path(base_path)/split/"masks"
    img_paths = list(IMG_DIR.glob(f"*{img_ext}"))
    mask_paths = list(MASK_DIR.glob(f"*{mask_ext}"))

    mask_dict = {}
    for m in mask_paths:
        stem = m.stem
        if '_mask' in stem:
            stem = stem.replace('_mask','')
        elif '_seg' in stem:
            stem = stem.replace('_seg','')
        mask_dict[stem] = m

    pairs = []
    for im in img_paths:
        key = im.stem
        if key in mask_dict:
            pairs.append((str(im), str(mask_dict[key])))
    print(f"Test samples: {len(pairs)}")
    return pairs

# --- ৪. Dataset ---
class TumorSegmentationTestDataset(Dataset):
    def __init__(self, pairs, augmentation=None):
        self.pairs = pairs
        self.augmentation = augmentation
    def __len__(self):
        return len(self.pairs)
    def __getitem__(self, idx):
        img_path, mask_path = self.pairs[idx]
        image = cv2.imread(img_path, cv2.IMREAD_COLOR)
        image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
        mask = cv2.imread(mask_path, cv2.IMREAD_GRAYSCALE)
        mask = np.where(mask>0,1.0,0.0).astype(np.float32)
        if image.ndim==2:
            image = cv2.cvtColor(image, cv2.COLOR_GRAY2RGB)
        if self.augmentation:
            sample = self.augmentation(image=image, mask=mask)
            image, mask = sample['image'], sample['mask']
        image = np.transpose(image,(2,0,1))
        mask = np.expand_dims(mask, axis=0)
        return torch.tensor(image,dtype=torch.float32), torch.tensor(mask,dtype=torch.float32), img_path

# --- ৫. Test Augmentations & Dataloader ---
TEST_AUGMENTATIONS = A.Compose([
    A.Resize(IMAGE_SIZE, IMAGE_SIZE),
    A.Normalize(mean=SIMPLE_MEAN,std=SIMPLE_STD,max_pixel_value=255.0)
])
test_pairs = get_data_pairs(BASE, IMG_EXT, MASK_EXT, split="test")
test_dataset = TumorSegmentationTestDataset(test_pairs, augmentation=TEST_AUGMENTATIONS)
test_loader = DataLoader(test_dataset, batch_size=BATCH_SIZE, shuffle=False)

# --- ৬. Model Load ---
model = smp.DeepLabV3Plus(
    encoder_name="timm-efficientnet-b3",
    encoder_weights=None,
    in_channels=3,
    classes=1,
    activation=None
).to(DEVICE)

if os.path.exists(SAVE_PATH):
    model.load_state_dict(torch.load(SAVE_PATH,map_location=DEVICE))
    print(f"✅ Model loaded from {SAVE_PATH}")
else:
    print("❌ Saved model not found. Aborting test.")
    raise FileNotFoundError

# --- ৭. Metrics Setup ---
dice_metric = smp.losses.DiceLoss(mode='binary', from_logits=False)
iou_metric = smp.losses.JaccardLoss(mode='binary', from_logits=False)

def calculate_metrics(y_pred_logits, y_true):
    y_pred_binary = (torch.sigmoid(y_pred_logits)>0.5).float()
    dice_score = 1.0 - dice_metric(y_pred_binary, y_true).item()
    iou_score = 1.0 - iou_metric(y_pred_binary, y_true).item()
    return dice_score, iou_score

# --- ৮. Test Loop ---
model.eval()
all_dice, all_iou = [], []
predictions = []

with torch.no_grad():
    for imgs, masks, paths in tqdm(test_loader, desc="Testing"):
        imgs, masks = imgs.to(DEVICE), masks.to(DEVICE)
        outputs = model(imgs)
        d,i = calculate_metrics(outputs, masks)
        all_dice.append(d)
        all_iou.append(i)
        # Save predictions for visualization
        preds = (torch.sigmoid(outputs)>0.5).float()
        for p, m, path in zip(preds, masks, paths):
            predictions.append((path, m.cpu().numpy().squeeze(), p.cpu().numpy().squeeze()))

mean_dice = np.mean(all_dice)
mean_iou = np.mean(all_iou)
print(f"\n✅ Test Dice: {mean_dice:.4f}, Test IoU: {mean_iou:.4f}")

# --- ৯. Random Test Images Plot (Original / Mask / Prediction) ---
def plot_random_predictions(predictions, n=5):
    sample = random.sample(predictions, n)
    plt.figure(figsize=(18,6))
    for i, (path, mask, pred) in enumerate(sample):
        plt.subplot(n,3,i*3+1)
        plt.imshow(cv2.imread(path)[:,:,::-1])
        plt.title("Original"); plt.axis('off')
        plt.subplot(n,3,i*3+2)
        plt.imshow(mask, cmap='gray')
        plt.title("Ground Truth"); plt.axis('off')
        plt.subplot(n,3,i*3+3)
        plt.imshow(pred, cmap='gray')
        plt.title("Prediction"); plt.axis('off')
    plt.tight_layout(); plt.show()

plot_random_predictions(predictions, n=5)



