def plot_random_predictions(predictions, n=NUM_RANDOM_IMAGES):
    sample = random.sample(predictions, n)
    plt.figure(figsize=(18,3*n))
    for i, (path, mask, pred) in enumerate(sample):
        plt.subplot(n,3,i*3+1)
        plt.imshow(cv2.imread(path)[:,:,::-1]); plt.title("Original"); plt.axis('off')
        plt.subplot(n,3,i*3+2)
        plt.imshow(mask, cmap='gray'); plt.title("Ground Truth"); plt.axis('off')
        plt.subplot(n,3,i*3+3)
        plt.imshow(pred, cmap='gray'); plt.title("Prediction"); plt.axis('off')
    plt.tight_layout(); plt.show()

