import timm
import segmentation_models_pytorch as smp
import albumentations as A
from sklearn.metrics import confusion_matrix, classification_report, roc_curve, auc
from sklearn.preprocessing import label_binarize

# optional hausdorff
try:
    from torchmetrics.functional import hausdorff_distance
    TORCHMETRICS_HAUSDORFF = True
except Exception:
    TORCHMETRICS_HAUSDORFF = False

# ---------------------------
# CONFIG - adjust if you want
# ---------------------------
DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print("Device:", DEVICE)

ROOT = "/content/drive/MyDrive/BRISC/brisc2025"   # change if needed
IMG_SIZE = 256
BATCH_CLS = 8
BATCH_SEG = 4
NUM_EPOCHS = 10
LR = 1e-4
PATIENCE = 5
SAVE_PATH = "/content/drive/MyDrive/BRISC/multitask_best.pth"

# ---------------------------
# Auto-locate classification & segmentation folders
# ---------------------------
def find_candidate(root, keywords):
    # search for a directory whose name contains any keyword
    for dirpath, dirnames, filenames in os.walk(root):
        base = os.path.basename(dirpath).lower()
        if any(k in base for k in keywords):
            return dirpath
    return None

# prefer exact expected names first
cls_root_candidates = [
    os.path.join(ROOT, "classification_task"),
    os.path.join(ROOT, "classification"),
    os.path.join(ROOT, "cls"),
]
seg_root_candidates = [
    os.path.join(ROOT, "segmentation_task"),
    os.path.join(ROOT, "segmentation"),
    os.path.join(ROOT, "seg"),
]

cls_root = next((p for p in cls_root_candidates if os.path.isdir(p)), None)
seg_root = next((p for p in seg_root_candidates if os.path.isdir(p)), None)

# fallback: try to find any folder matching keyword deeper
if cls_root is None:
    cls_root = find_candidate(ROOT, ["classification", "class", "cls"])
if seg_root is None:
    seg_root = find_candidate(ROOT, ["segmentation", "seg", "masks", "masks_and_images"])

print("Detected classification root:", cls_root)
print("Detected segmentation root:", seg_root)

# ---------------------------
# Build classification dataset (ImageFolder if possible)
# ---------------------------
if cls_root is None:
    raise FileNotFoundError("Could not find classification folder under ROOT. Place it in 'classification_task' or similar.")

train_folder_cls = os.path.join(cls_root, "train")
test_folder_cls  = os.path.join(cls_root, "test")

# if train/test subfolders missing, try direct image folders
if not (os.path.isdir(train_folder_cls) and os.path.isdir(test_folder_cls)):
    # try if cls_root itself contains class subfolders
    if any(os.path.isdir(os.path.join(cls_root, d)) for d in os.listdir(cls_root)):
        # assume structure: cls_root/<class_name>/*.png  and no explicit train/test; we'll split
        print("No explicit train/test folders found under classification root — using whole folder as dataset and splitting.")
        train_folder_cls = cls_root
        test_folder_cls = None
    else:
        raise FileNotFoundError("Cannot find classification train/test folders or class subfolders in classification root.")

# transforms
train_tf_cls = transforms.Compose([
    transforms.Resize((IMG_SIZE, IMG_SIZE)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(10),
    transforms.ColorJitter(0.1,0.1,0.1),
    transforms.ToTensor(),
    transforms.Normalize([0.485,0.456,0.406],[0.229,0.224,0.225])
])
test_tf_cls = transforms.Compose([
    transforms.Resize((IMG_SIZE, IMG_SIZE)),
    transforms.ToTensor(),
    transforms.Normalize([0.485,0.456,0.406],[0.229,0.224,0.225])
])

if test_folder_cls is not None:
    train_ds_all = datasets.ImageFolder(train_folder_cls, transform=train_tf_cls)
    # create validation split from train folder
    val_split = 0.15
    n_total = len(train_ds_all)
    n_val = max(1, int(val_split * n_total))
    n_train = n_total - n_val
    train_ds, val_ds = torch.utils.data.random_split(train_ds_all, [n_train, n_val])
    test_ds = datasets.ImageFolder(test_folder_cls, transform=test_tf_cls)
else:
    # single folder: split into train/val/test
    all_ds = datasets.ImageFolder(train_folder_cls, transform=train_tf_cls)
    n_total = len(all_ds)
    n_test = max(1, int(0.15 * n_total))
    n_val = max(1, int(0.15 * (n_total - n_test)))
    n_train = n_total - n_val - n_test
    train_ds, val_ds, test_ds = torch.utils.data.random_split(all_ds, [n_train, n_val, n_test])

train_loader_cls = DataLoader(train_ds, batch_size=BATCH_CLS, shuffle=True, num_workers=2, pin_memory=True)
val_loader_cls   = DataLoader(val_ds, batch_size=BATCH_CLS, shuffle=False, num_workers=2, pin_memory=True)
test_loader_cls  = DataLoader(test_ds, batch_size=BATCH_CLS, shuffle=False, num_workers=2, pin_memory=True)

class_names = train_ds.dataset.classes if isinstance(train_ds, torch.utils.data.Subset) else train_ds.classes
NUM_CLASSES = len(class_names)
print("Classes:", class_names)

# ---------------------------
# Build segmentation pairs if possible
# Expecting seg_root/{train,test}/{images,masks}
# ---------------------------
def list_img_files(folder):
    return sorted([f for f in os.listdir(folder) if not f.startswith('.') and f.lower().endswith(('.png','.jpg','.jpeg'))])

train_pairs_seg = []
test_pairs_seg = []
seg_on = False
if seg_root is not None:
    def get_pairs(base, split):
        img_dir = os.path.join(base, split, "images")
        mask_dir = os.path.join(base, split, "masks")
        if os.path.isdir(img_dir) and os.path.isdir(mask_dir):
            imgs = list_img_files(img_dir)
            masks = list_img_files(mask_dir)
            pairs = [(os.path.join(img_dir, f), os.path.join(mask_dir, f)) for f in imgs if f in masks]
            return pairs
        return []

    train_pairs_seg = get_pairs(seg_root, "train")
    test_pairs_seg = get_pairs(seg_root, "test")

    # fallback: if seg_root/images and seg_root/masks directly
    if len(train_pairs_seg) == 0:
        if os.path.isdir(os.path.join(seg_root, "images")) and os.path.isdir(os.path.join(seg_root, "masks")):
            imgs = list_img_files(os.path.join(seg_root, "images"))
            masks = list_img_files(os.path.join(seg_root, "masks"))
            train_pairs_seg = [(os.path.join(seg_root, "images", f), os.path.join(seg_root, "masks", f)) for f in imgs if f in masks]
    if len(train_pairs_seg) + len(test_pairs_seg) > 0:
        seg_on = True

print("Seg train samples:", len(train_pairs_seg), "| Seg test samples:", len(test_pairs_seg))

# ---------------------------
# Segmentation dataset class
# ---------------------------
IMG_MEAN = (0.485,0.456,0.406); IMG_STD = (0.229,0.224,0.225)
train_aug_seg = A.Compose([A.Resize(IMG_SIZE,IMG_SIZE), A.HorizontalFlip(p=0.5), A.RandomRotate90(p=0.5), A.Normalize(mean=IMG_MEAN, std=IMG_STD)])
test_aug_seg  = A.Compose([A.Resize(IMG_SIZE,IMG_SIZE), A.Normalize(mean=IMG_MEAN, std=IMG_STD)])

class SegDataset(Dataset):
    def __init__(self, pairs, aug=None):
        self.pairs = pairs
        self.aug = aug
    def __len__(self):
        return len(self.pairs)
    def __getitem__(self, idx):
        img_path, mask_path = self.pairs[idx]
        img = np.array(Image.open(img_path).convert("RGB"))
        mask = np.array(Image.open(mask_path).convert("L"))
        mask = (mask > 0).astype('float32')
        if self.aug:
            aug = self.aug(image=img, mask=mask)
            img, mask = aug['image'], aug['mask']
        img = img.astype('float32') / 255.0
        img = np.transpose(img, (2,0,1))
        mask = np.expand_dims(mask, 0).astype('float32')
        return torch.tensor(img, dtype=torch.float32), torch.tensor(mask, dtype=torch.float32)

train_loader_seg = val_loader_seg = test_loader_seg = None
if seg_on and len(train_pairs_seg)>0:
    random.shuffle(train_pairs_seg)
    val_sz = max(1, int(0.2 * len(train_pairs_seg)))
    train_pairs_split = train_pairs_seg[:-val_sz] if len(train_pairs_seg)>1 else train_pairs_seg
    val_pairs_split = train_pairs_seg[-val_sz:] if len(train_pairs_seg)>1 else train_pairs_seg
    train_loader_seg = DataLoader(SegDataset(train_pairs_split, aug=train_aug_seg), batch_size=BATCH_SEG, shuffle=True, num_workers=2, pin_memory=True)
    val_loader_seg   = DataLoader(SegDataset(val_pairs_split, aug=test_aug_seg), batch_size=BATCH_SEG, shuffle=False, num_workers=2, pin_memory=True)
else:
    print("⚠️ Segmentation training skipped (no seg pairs).")

if seg_on and len(test_pairs_seg)>0:
    test_loader_seg  = DataLoader(SegDataset(test_pairs_seg, aug=test_aug_seg), batch_size=1, shuffle=False, num_workers=1, pin_memory=True)
else:
    print("⚠️ Segmentation test skipped (no seg test pairs).")

# ---------------------------
# MODEL: separate classification backbone + optional Unet
# (This avoids decoder/encoder calling conflicts)
# ---------------------------
# classification backbone (timm)
backbone = timm.create_model('efficientnet_b3', pretrained=True, num_classes=0, global_pool='avg')  # returns feature vector
feat_dim = backbone.num_features
cls_head = nn.Linear(feat_dim, NUM_CLASSES)

# segmentation model (only if seg_on)
seg_model = None
if seg_on:
    # SMP Unet encoder uses timm encoder ; make sure encoder name available in your SMP version
    try:
        seg_model = smp.Unet(encoder_name="timm-efficientnet-b3", encoder_weights="imagenet", in_channels=3, classes=1, activation=None)
        print("Segmentation model created (Unet).")
    except Exception as e:
        # try fallback encoder name
        seg_model = smp.Unet(encoder_name="efficientnet-b3", encoder_weights="imagenet", in_channels=3, classes=1, activation=None)
        print("Segmentation model created (Unet) with fallback encoder name.")

# wrap into single container
class MultiNet(nn.Module):
    def __init__(self, backbone, cls_head, seg_model=None):
        super().__init__()
        self.backbone = backbone
        self.cls_head = cls_head
        self.seg_model = seg_model
    def forward(self, x, seg=False):
        # classification path via backbone -> avgpool features
        feats = self.backbone(x)  # shape (B, feat_dim)
        cls_out = self.cls_head(feats)
        seg_out = None
        if seg and (self.seg_model is not None):
            # call full seg_model forward (safe)
            seg_out = self.seg_model(x)   # logits (B,1,H,W)
        return cls_out, seg_out

model = MultiNet(backbone, cls_head, seg_model).to(DEVICE)

# ---------------------------
# Loss, optimizer, metrics
# ---------------------------
import torch.nn.functional as F
criterion_cls = nn.CrossEntropyLoss()
criterion_seg = smp.losses.DiceLoss(mode='binary', from_logits=True)
optimizer = optim.Adam(list(model.parameters()), lr=LR)

def batch_dice(pred_logits, true_mask):
    pred = torch.sigmoid(pred_logits)
    pred_bin = (pred > 0.5).float()
    inter = (pred_bin * true_mask).sum(dim=(1,2,3))
    denom = pred_bin.sum(dim=(1,2,3)) + true_mask.sum(dim=(1,2,3))
    dice = (2*inter + 1e-7) / (denom + 1e-7)
    return dice.detach().cpu().numpy()

def batch_iou(pred_logits, true_mask):
    pred = torch.sigmoid(pred_logits)
    pred_bin = (pred > 0.5).float()
    inter = (pred_bin * true_mask).sum(dim=(1,2,3))
    union = pred_bin.sum(dim=(1,2,3)) + true_mask.sum(dim=(1,2,3)) - inter
    iou = (inter + 1e-7) / (union + 1e-7)
    return iou.detach().cpu().numpy()

# ---------------------------
# TRAIN loop (paired: cycle seg)
# ---------------------------
history = {"train_loss_cls":[], "train_loss_seg":[], "train_acc":[], "val_acc":[], "train_dice":[], "val_dice":[], "train_iou":[], "val_iou":[]}
best_val = float('inf'); no_imp = 0

for epoch in range(1, NUM_EPOCHS+1):
    model.train()
    running_cls = 0.0; running_seg = 0.0
    correct = 0; total = 0
    dice_accum=[]; iou_accum=[]
    seg_iter = iter(train_loader_seg) if train_loader_seg is not None else None

    loop = tqdm(enumerate(train_loader_cls), total=len(train_loader_cls), desc=f"Epoch {epoch}/{NUM_EPOCHS}")
    for i, (imgs_cls, labels) in loop:
        imgs_cls = imgs_cls.to(DEVICE); labels = labels.to(DEVICE)
        # get seg batch if available (cycle)
        seg_imgs = seg_masks = None
        if seg_iter is not None:
            try:
                seg_imgs, seg_masks = next(seg_iter)
            except StopIteration:
                seg_iter = iter(train_loader_seg)
                try:
                    seg_imgs, seg_masks = next(seg_iter)
                except StopIteration:
                    seg_imgs = seg_masks = None

        optimizer.zero_grad()
        out_cls, _ = model(imgs_cls, seg=False)
        loss_cls = criterion_cls(out_cls, labels)
        loss_seg = torch.tensor(0.0, device=DEVICE)
        if seg_imgs is not None:
            seg_imgs = seg_imgs.to(DEVICE); seg_masks = seg_masks.to(DEVICE)
            _, seg_logits = model(seg_imgs, seg=True)
            loss_seg = criterion_seg(seg_logits, seg_masks)
        loss = loss_cls + loss_seg
        loss.backward(); optimizer.step()

        running_cls += loss_cls.item(); running_seg += float(loss_seg.item() if isinstance(loss_seg, torch.Tensor) else loss_seg)
        preds = torch.argmax(out_cls, dim=1)
        correct += (preds == labels).sum().item(); total += labels.size(0)

        if seg_imgs is not None:
            dice_accum.extend(list(batch_dice(seg_logits, seg_masks)))
            iou_accum.extend(list(batch_iou(seg_logits, seg_masks)))

        loop.set_postfix({"loss_cls": running_cls/(i+1), "loss_seg": running_seg/(i+1), "acc": correct/total})

    # epoch stats
    train_loss_cls = running_cls / len(train_loader_cls)
    train_loss_seg = running_seg / (len(train_loader_seg) if train_loader_seg is not None and len(train_loader_seg)>0 else 1)
    train_acc = correct/total if total>0 else 0.0
    train_dice = np.nanmean(dice_accum) if len(dice_accum)>0 else float("nan")
    train_iou = np.nanmean(iou_accum) if len(iou_accum)>0 else float("nan")

    history["train_loss_cls"].append(train_loss_cls); history["train_loss_seg"].append(train_loss_seg)
    history["train_acc"].append(train_acc); history["train_dice"].append(train_dice); history["train_iou"].append(train_iou)

    # validation (cls + seg if available)
    model.eval()
    val_correct = 0; val_total = 0
    val_dices=[]; val_ious=[]
    val_loss_cls = 0.0; val_loss_seg = 0.0

    with torch.no_grad():
        for imgs_v, labels_v in val_loader_cls:
            imgs_v = imgs_v.to(DEVICE); labels_v = labels_v.to(DEVICE)
            outc, _ = model(imgs_v, seg=False)
            val_loss_cls += criterion_cls(outc, labels_v).item()
            preds_v = torch.argmax(outc, dim=1)
            val_correct += (preds_v == labels_v).sum().item(); val_total += labels_v.size(0)

        if val_loader_seg is not None:
            for imgs_s, masks_s in val_loader_seg:
                imgs_s = imgs_s.to(DEVICE); masks_s = masks_s.to(DEVICE)
                _, seg_logits_v = model(imgs_s, seg=True)
                val_loss_seg += criterion_seg(seg_logits_v, masks_s).item()
                val_dices.extend(list(batch_dice(seg_logits_v, masks_s)))
                val_ious.extend(list(batch_iou(seg_logits_v, masks_s)))

    val_acc = val_correct/val_total if val_total>0 else 0.0
    val_dice = np.nanmean(val_dices) if len(val_dices)>0 else float("nan")
    val_iou = np.nanmean(val_ious) if len(val_ious)>0 else float("nan")
    avg_val_loss = (val_loss_cls / (len(val_loader_cls) if len(val_loader_cls)>0 else 1)) + (val_loss_seg / (len(val_loader_seg) if val_loader_seg is not None and len(val_loader_seg)>0 else 1))

    history["val_acc"].append(val_acc); history["val_dice"].append(val_dice); history["val_iou"].append(val_iou)
    print(f"Epoch {epoch} -> Train Acc: {train_acc:.4f} Val Acc: {val_acc:.4f} Train Dice: {train_dice:.4f} Val Dice: {val_dice:.4f}")

    # checkpoint
    if avg_val_loss < best_val:
        best_val = avg_val_loss; no_imp = 0
        torch.save({'epoch': epoch, 'model_state': model.state_dict(), 'optimizer': optimizer.state_dict(), 'history': history, 'class_names': class_names}, SAVE_PATH)
        print("Saved best model:", SAVE_PATH)
    else:
        no_imp += 1
        if no_imp >= PATIENCE:
            print("Early stopping.")
            break

# ---------------------------
# Test evaluation
# ---------------------------
if os.path.exists(SAVE_PATH):
    ckpt = torch.load(SAVE_PATH, map_location=DEVICE)
    model.load_state_dict(ckpt['model_state'])
    print("Loaded saved model.")

model.eval()
all_true=[]; all_pred=[]; all_probs=[]
with torch.no_grad():
    for imgs_t, labels_t in tqdm(test_loader_cls, desc="Cls test"):
        imgs_t = imgs_t.to(DEVICE); labels_t = labels_t.to(DEVICE)
        outc, _ = model(imgs_t, seg=False)
        probs = F.softmax(outc, dim=1).cpu().numpy()
        preds = torch.argmax(outc, dim=1).cpu().numpy()
        all_probs.extend(list(probs)); all_pred.extend(list(preds)); all_true.extend(list(labels_t.cpu().numpy()))

# seg test
seg_dice_list=[]; seg_iou_list=[]; seg_hd_list=[]; seg_visuals=[]
if test_loader_seg is not None:
    with torch.no_grad():
        for imgs_s, masks_s in tqdm(test_loader_seg, desc="Seg test"):
            imgs_s = imgs_s.to(DEVICE); masks_s = masks_s.to(DEVICE)
            _, seg_logits_s = model(imgs_s, seg=True)
            seg_pred = torch.sigmoid(seg_logits_s) > 0.5
            seg_dice_list.extend(list(batch_dice(seg_logits_s, masks_s)))
            seg_iou_list.extend(list(batch_iou(seg_logits_s, masks_s)))
            if TORCHMETRICS_HAUSDORFF:
                try:
                    hd_vals = hausdorff_distance(seg_pred.squeeze(1).to(torch.float), masks_s.squeeze(1).to(torch.float))
                    if isinstance(hd_vals, torch.Tensor):
                        hd_vals = hd_vals.detach().cpu().numpy()
                        if hd_vals.ndim==0: hd_vals=[float(hd_vals)]
                        else: hd_vals=list(hd_vals)
                    seg_hd_list.extend(hd_vals)
                except Exception:
                    seg_hd_list.extend([float('nan')] * seg_pred.shape[0])
            else:
                seg_hd_list.extend([float('nan')] * seg_pred.shape[0])
            imgs_cpu = imgs_s.cpu().numpy(); masks_cpu = masks_s.cpu().numpy(); preds_cpu = seg_pred.cpu().numpy().astype(np.uint8)
            for i in range(imgs_cpu.shape[0]):
                img_np = np.transpose(imgs_cpu[i], (1,2,0))
                img_show = np.clip((img_np * np.array(IMG_STD)[:,None,None]) + np.array(IMG_MEAN)[:,None,None], 0,1)
                gt_mask = masks_cpu[i].squeeze(0); pr_mask = preds_cpu[i].squeeze(0)
                seg_visuals.append((img_show, gt_mask, pr_mask))

# ---------------------------
# Reports & plots
# ---------------------------
import torch.nn.functional as F
print("\n=== Classification Report ===")
print(classification_report(all_true, all_pred, target_names=class_names, zero_division=0))

cm = confusion_matrix(all_true, all_pred)
plt.figure(figsize=(6,5)); plt.imshow(cm, cmap='Blues'); plt.colorbar()
ticks = np.arange(len(class_names)); plt.xticks(ticks, class_names, rotation=45); plt.yticks(ticks, class_names)
for i in range(cm.shape[0]):
    for j in range(cm.shape[1]):
        plt.text(j, i, cm[i,j], ha='center', va='center')
plt.xlabel('Predicted'); plt.ylabel('True'); plt.tight_layout(); plt.show()

if len(all_probs) > 0 and NUM_CLASSES >= 2:
    y_true_bin = label_binarize(all_true, classes=list(range(NUM_CLASSES)))
    y_score = np.array(all_probs)
    plt.figure(figsize=(8,6))
    for i in range(NUM_CLASSES):
        try:
            fpr, tpr, _ = roc_curve(y_true_bin[:,i], y_score[:,i]); roc_auc = auc(fpr,tpr)
            plt.plot(fpr, tpr, label=f"{class_names[i]} (AUC={roc_auc:.3f})")
        except Exception:
            pass
    plt.plot([0,1],[0,1],'k--'); plt.legend(); plt.xlabel("FPR"); plt.ylabel("TPR"); plt.title("ROC"); plt.grid(True); plt.show()

# training curves
plt.figure(figsize=(12,5))
plt.subplot(1,2,1); plt.plot(history["train_acc"], label="Train Acc"); plt.plot(history["val_acc"], label="Val Acc"); plt.title("Accuracy"); plt.legend(); plt.grid(True)
plt.subplot(1,2,2); plt.plot(history["train_loss_cls"], label="Train Loss CLS"); plt.plot(history["train_loss_seg"], label="Train Loss SEG"); plt.title("Loss"); plt.legend(); plt.grid(True)
plt.show()

if len(seg_dice_list)>0:
    print(f"\nSegmentation test (n={len(seg_dice_list)}): Dice mean={np.mean(seg_dice_list):.4f}, IoU mean={np.mean(seg_iou_list):.4f}")
    if all([not np.isnan(x) for x in seg_hd_list]):
        print(f"Hausdorff mean={np.mean(seg_hd_list):.4f}")
    else:
        print("Hausdorff: not computed (torchmetrics missing/incompatible)")
    n = min(6, len(seg_visuals)); samples = random.sample(seg_visuals, n)
    plt.figure(figsize=(12,4*n))
    for i,(img,gt,pr) in enumerate(samples):
        plt.subplot(n,3,i*3+1); plt.imshow(np.clip(img,0,1)); plt.title("Image"); plt.axis('off')
        plt.subplot(n,3,i*3+2); plt.imshow(gt, cmap='gray'); plt.title("GT"); plt.axis('off')
        plt.subplot(n,3,i*3+3); plt.imshow(pr, cmap='gray'); plt.title("Pred"); plt.axis('off')
    plt.tight_layout(); plt.show()
else:
    print("\nNo segmentation test results to show.")

print("\n✅ Done.")

