# ----------------------------
# Model: EfficientNet-B3 with classifier head
# ----------------------------
class ClassifierModel(nn.Module):
    def __init__(self, num_classes):
        super().__init__()
        self.backbone = timm.create_model("efficientnet_b3", pretrained=True)
        in_features = self.backbone.classifier.in_features
        self.backbone.classifier = nn.Identity()
        self.head = nn.Sequential(
            nn.Linear(in_features, 512),
            nn.ReLU(),
            nn.Dropout(0.4),
            nn.Linear(512, num_classes)
        )
    def forward(self, x):
        feat = self.backbone(x)
        out = self.head(feat)
        return out

model = ClassifierModel(num_classes).to(device)
print(model)

# ----------------------------
# Loss: Focal + Label smoothing wrapper (optional)
# ----------------------------
class LabelSmoothingCrossEntropy(nn.Module):
    def __init__(self, smoothing=0.0):
        super().__init__()
        self.smoothing = smoothing
    def forward(self, preds, target):
        log_probs = F.log_softmax(preds, dim=-1)
        if self.smoothing == 0:
            return F.nll_loss(log_probs, target)
        n = preds.size(-1)
        with torch.no_grad():
            true_dist = torch.zeros_like(preds)
            true_dist.fill_(self.smoothing / (n - 1))
            true_dist.scatter_(1, target.data.unsqueeze(1), 1.0 - self.smoothing)
        return torch.mean(torch.sum(-true_dist * log_probs, dim=-1))

class FocalLoss(nn.Module):
    def __init__(self, gamma=2.0, weight=None):
        super().__init__()
        self.gamma = gamma
        self.weight = weight
    def forward(self, inputs, targets):
        ce_loss = F.cross_entropy(inputs, targets, weight=self.weight, reduction='none')
        pt = torch.exp(-ce_loss)
        focal = ((1 - pt) ** self.gamma) * ce_loss
        return focal.mean()

# choose loss
use_label_smoothing = True
use_focal = True
if use_focal:
    criterion = FocalLoss(gamma=2.0)
elif use_label_smoothing:
    criterion = LabelSmoothingCrossEntropy(smoothing=0.1)
else:
    criterion = nn.CrossEntropyLoss()

# ----------------------------
# Optimizer + Scheduler (AdamW + OneCycleLR)
# ----------------------------
optimizer = optim.AdamW(model.parameters(), lr=2e-4, weight_decay=1e-4)
total_steps = num_epochs * len(train_loader)
scheduler = optim.lr_scheduler.OneCycleLR(
    optimizer, max_lr=2e-3, steps_per_epoch=len(train_loader), epochs=num_epochs, pct_start=0.2
)

# ----------------------------
# MixUp + CutMix utility
# ----------------------------
def mixup_data(x, y, alpha=0.4):
    if alpha <= 0:
        return x, y, None, None, 1.0
    lam = np.random.beta(alpha, alpha)
    batch_size = x.size()[0]
    index = torch.randperm(batch_size).to(device)
    mixed_x = lam * x + (1 - lam) * x[index, :]
    y_a, y_b = y, y[index]
    return mixed_x, y_a, y_b, index, lam

# ----------------------------
# Training & validation loops with checkpointing & early stopping
# ----------------------------
best_val_acc = 0.0
epochs_no_improve = 0
early_stop_patience = 6
history = {"train_loss":[], "val_loss":[], "train_acc":[], "val_acc":[]}

for epoch in range(num_epochs):
    model.train()
    running_loss = 0.0
    running_correct = 0
    total = 0
    t0 = time.time()

    for imgs, labels, _ in tqdm(train_loader, desc=f"Train Epoch {epoch+1}/{num_epochs}"):
        imgs = imgs.to(device)
        labels = labels.to(device)

        # MixUp augmentation half the batch time
        do_mixup = np.random.rand() < 0.5
        if do_mixup:
            imgs, y_a, y_b, index, lam = mixup_data(imgs, labels, alpha=mixup_alpha)
            outputs = model(imgs)
            loss = lam * criterion(outputs, y_a) + (1 - lam) * criterion(outputs, y_b)
        else:
            outputs = model(imgs)
            loss = criterion(outputs, labels)

        optimizer.zero_grad()
        loss.backward()
        optimizer.step()
        scheduler.step()

        running_loss += loss.item() * imgs.size(0)
        preds = outputs.argmax(dim=1)
        # if mixup, approximate accuracy with max of soft labels
        if do_mixup:
            running_correct += (lam * (preds == y_a).sum().item() + (1-lam) * (preds == y_b).sum().item())
        else:
            running_correct += (preds == labels).sum().item()
        total += labels.size(0)

    train_loss = running_loss / total
    train_acc = running_correct / total

    # Validation
    model.eval()
    val_loss = 0.0
    val_correct = 0
    val_total = 0
    with torch.no_grad():
        for imgs, labels, _ in val_loader:
            imgs = imgs.to(device)
            labels = labels.to(device)
            outputs = model(imgs)
            loss = criterion(outputs, labels)
            val_loss += loss.item() * imgs.size(0)
            preds = outputs.argmax(dim=1)
            val_correct += (preds == labels).sum().item()
            val_total += labels.size(0)

    val_loss = val_loss / val_total
    val_acc = val_correct / val_total

    history['train_loss'].append(train_loss)
    history['val_loss'].append(val_loss)
    history['train_acc'].append(train_acc)
    history['val_acc'].append(val_acc)

    elapsed = time.time() - t0
    print(f"Epoch {epoch+1} - Train loss: {train_loss:.4f}, acc: {train_acc:.4f} | Val loss: {val_loss:.4f}, acc: {val_acc:.4f} | time: {elapsed:.1f}s")

    # Checkpointing best model
    if val_acc > best_val_acc:
        best_val_acc = val_acc
        torch.save(model.state_dict(), os.path.join(checkpoint_dir, "best_model.pth"))
        print("Saved best model.")
        epochs_no_improve = 0
    else:
        epochs_no_improve += 1
        print(f"No improvement count: {epochs_no_improve}/{early_stop_patience}")

    if epochs_no_improve >= early_stop_patience:
        print("Early stopping triggered.")
        break

