# ----------------------------
# Test-time augmentation (TTA) prediction
# ----------------------------
def predict_tta(model, image_path, tta_runs=5):
    img_bgr = cv2.imread(image_path)
    img_rgb = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB)
    preds = []
    for _ in range(tta_runs):
        aug = tta_transform(image=img_rgb)
        x = aug['image'].unsqueeze(0).to(device)
        with torch.no_grad():
            out = model(x)
            probs = F.softmax(out, dim=1).cpu().numpy()[0]
        preds.append(probs)
    return np.mean(preds, axis=0)

# Full test evaluation
all_y, all_pred, all_probs, all_paths = [], [], [], []
for path, true_label in zip(test_items, test_labels):
    probs = predict_tta(model, path, tta_runs=tta_transforms)
    pred = np.argmax(probs)
    all_y.append(true_label)
    all_pred.append(pred)
    all_probs.append(probs)
    all_paths.append(path)

acc = accuracy_score(all_y, all_pred)
print(f"Test Accuracy (with TTA): {acc:.6f}")

# Confusion matrix & classification report
