# ---------------------------- Grad-CAM ----------------------------
class GradCAM:
    def __init__(self, model, target_layer):
        self.model = model
        self.model.eval()
        self.gradients = None
        self.activations = None
        target_layer.register_forward_hook(lambda m, i, o: setattr(self,'activations',o.detach()))
        target_layer.register_backward_hook(lambda m, grad_in, grad_out: setattr(self,'gradients',grad_out[0].detach()))

    def __call__(self, input_tensor, class_idx=None):
        input_tensor = input_tensor.to(device)
        out = self.model(input_tensor)
        if class_idx is None:
            class_idx = torch.argmax(out, dim=1).item()
        score = out[:,class_idx]
        self.model.zero_grad()
        score.backward(retain_graph=True)
        gradients = self.gradients.cpu().numpy()[0]
        activations = self.activations.cpu().numpy()[0]
        weights = np.mean(gradients, axis=(1,2))
        cam = np.zeros(activations.shape[1:], dtype=np.float32)
        for i,w in enumerate(weights):
            cam += w*activations[i,:,:]
        cam = np.maximum(cam,0)
        cam = cv2.resize(cam,(img_size,img_size))
        cam = (cam-cam.min())/(cam.max()-cam.min()+1e-8)
        return cam, class_idx

def find_target_layer(model):
    backbone = model.backbone
    for name,module in reversed(list(backbone.named_modules())):
        if hasattr(module,'weight') and module.weight is not None and module.weight.ndim==4:
            return module
    return backbone

target_layer = find_target_layer(model)
grad_cam = GradCAM(model, target_layer)

# Grad-CAM overlay save
preds_by_class = {i:[] for i in range(num_classes)}
for p, prob, true in zip(all_paths, all_probs, all_y):
    pred = np.argmax(prob)
    conf = prob[pred]
    preds_by_class[pred].append((p, conf, true))

topk=3
gradcam_out_dir = os.path.join(outputs_dir,"gradcam")
os.makedirs(gradcam_out_dir,exist_ok=True)

for cls_id, items in preds_by_class.items():
    items_sorted = sorted(items, key=lambda x: x[1], reverse=True)[:topk]
    for i,(path, conf, true_label) in enumerate(items_sorted):
        img_bgr = cv2.imread(path)
        img_rgb = cv2.cvtColor(img_bgr, cv2.COLOR_BGR2RGB)
        aug = val_transform(image=img_rgb)
        x = aug['image'].unsqueeze(0)
        cam, predicted = grad_cam(x, class_idx=None)
        heatmap = cv2.applyColorMap(np.uint8(255*cam), cv2.COLORMAP_JET)
        heatmap = cv2.cvtColor(heatmap, cv2.COLOR_BGR2RGB)
        orig = cv2.resize(img_rgb,(img_size,img_size))
        overlay = (0.6*heatmap + 0.4*orig).astype(np.uint8)
        save_path = os.path.join(gradcam_out_dir,f"class_{classes[cls_id]}_rank{i+1}_pred{classes[predicted]}_true{classes[true_label]}_conf{conf:.3f}.jpg")
        Image.fromarray(overlay).save(save_path)
        print("Saved Grad-CAM:", save_path)

