# ============================================
# IMPORTS
# ============================================
import os, random, cv2, numpy as np, matplotlib.pyplot as plt
from tqdm import tqdm
from sklearn.metrics import classification_report, confusion_matrix, roc_curve, auc
from sklearn.model_selection import train_test_split
from collections import Counter
import seaborn as sns
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import DataLoader, Subset
from torchvision import transforms, models, datasets

# ============================================
# SETUP
# ============================================
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
BASE_DIR = "/content/drive/MyDrive/BRISC/brisc2025"
VAL_SPLIT = 0.2
BATCH_SIZE = 8
EPOCHS = 20
LR = 1e-4
SEED = 42
torch.manual_seed(SEED)
np.random.seed(SEED)
random.seed(SEED)

# ============================================
# DATA AUGMENTATION + NORMALIZATION
# ============================================
train_tf = transforms.Compose([
    transforms.Resize((224,224)),
    transforms.RandomHorizontalFlip(),
    transforms.RandomRotation(10),
    transforms.ColorJitter(0.2,0.2,0.2,0.1),
    transforms.ToTensor(),
    transforms.Normalize([0.485,0.456,0.406],[0.229,0.224,0.225])
])

val_tf = transforms.Compose([
    transforms.Resize((224,224)),
    transforms.CenterCrop(224),
    transforms.ToTensor(),
    transforms.Normalize([0.485,0.456,0.406],[0.229,0.224,0.225])
])

# ============================================
# DATASET LOAD (ImageFolder)
# ============================================
CLS_TRAIN = os.path.join(BASE_DIR,"classification_task/train")
CLS_TEST  = os.path.join(BASE_DIR,"classification_task/test")

full_dataset = datasets.ImageFolder(CLS_TRAIN, transform=train_tf)
classes = full_dataset.classes
print("✅ Classes:", classes)

# STRATIFIED SPLIT
train_idx, val_idx = train_test_split(
    np.arange(len(full_dataset.targets)),
    test_size=VAL_SPLIT,
    stratify=full_dataset.targets,
    random_state=SEED
)
train_data = Subset(full_dataset, train_idx)
val_data   = Subset(datasets.ImageFolder(CLS_TRAIN, transform=val_tf), val_idx)
test_data  = datasets.ImageFolder(CLS_TEST, transform=val_tf)

train_loader = DataLoader(train_data, batch_size=BATCH_SIZE, shuffle=True)
val_loader   = DataLoader(val_data, batch_size=BATCH_SIZE)
test_loader  = DataLoader(test_data, batch_size=BATCH_SIZE)

# ============================================
# CLASS WEIGHTS (to handle imbalance)
# ============================================
counts = Counter(full_dataset.targets)
total = sum(counts.values())
class_weights = [total/c for c in counts.values()]
class_weights = torch.tensor(class_weights, dtype=torch.float).to(device)
print("📊 Class Weights:", class_weights)

# ============================================
# MODEL SETUP
# ============================================
model_cls = models.efficientnet_b3(weights="IMAGENET1K_V1")
model_cls.classifier[1] = nn.Linear(model_cls.classifier[1].in_features, len(classes))
model_cls = model_cls.to(device)

criterion_cls = nn.CrossEntropyLoss(weight=class_weights)
optimizer_cls = torch.optim.Adam(model_cls.parameters(), lr=LR)
scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(optimizer_cls, mode='min', factor=0.3, patience=2)

# ============================================
# TRAINING LOOP
# ============================================
train_losses, val_losses, train_accs, val_accs = [], [], [], []

for epoch in range(EPOCHS):
    model_cls.train()
    correct, total, running_loss = 0,0,0

    for imgs, labels in tqdm(train_loader, desc=f"Epoch {epoch+1}/{EPOCHS}"):
        imgs, labels = imgs.to(device), labels.to(device)
        optimizer_cls.zero_grad()
        out = model_cls(imgs)
        loss = criterion_cls(out, labels)
        loss.backward()
        optimizer_cls.step()

        running_loss += loss.item()
        _, pred = torch.max(out, 1)
        correct += (pred==labels).sum().item()
        total += labels.size(0)

    train_acc = correct/total
    train_losses.append(running_loss/len(train_loader))
    train_accs.append(train_acc)

    # ---------------- VAL ----------------
    model_cls.eval()
    val_correct, val_total, val_loss = 0,0,0
    with torch.no_grad():
        for imgs, labels in val_loader:
            imgs, labels = imgs.to(device), labels.to(device)
            out = model_cls(imgs)
            loss = criterion_cls(out, labels)
            val_loss += loss.item()
            _, pred = torch.max(out,1)
            val_correct += (pred==labels).sum().item()
            val_total += labels.size(0)

    val_acc = val_correct/val_total
    val_losses.append(val_loss/len(val_loader))
    val_accs.append(val_acc)
    scheduler.step(val_loss/len(val_loader))

    print(f"✅ Epoch [{epoch+1}/{EPOCHS}] | TrainAcc={train_acc:.3f} | ValAcc={val_acc:.3f}")

torch.save(model_cls.state_dict(), os.path.join(BASE_DIR, "cls_best.pth"))

# ============================================
# EVALUATION
# ============================================
model_cls.eval()
y_true, y_pred, y_score = [], [], []

with torch.no_grad():
    for imgs, labels in test_loader:
        imgs, labels = imgs.to(device), labels.to(device)
        out = model_cls(imgs)
        _, pred = torch.max(out,1)
        y_true.extend(labels.cpu().numpy())
        y_pred.extend(pred.cpu().numpy())
        y_score.extend(F.softmax(out, dim=1).cpu().numpy())

print("\n📄 Classification Report:\n")
print(classification_report(y_true, y_pred, target_names=classes))

