# ============================================
# GRAD-CAM FUNCTION
# ============================================
def grad_cam(model, img, target_layer):
    gradients, activations = [], []

    def backward_hook(module, grad_in, grad_out):
        gradients.append(grad_out[0].detach())

    def forward_hook(module, inp, out):
        activations.append(out.detach())

    h1 = target_layer.register_forward_hook(forward_hook)
    h2 = target_layer.register_full_backward_hook(backward_hook)

    model.eval()
    img = img.unsqueeze(0).to(device)
    out = model(img)
    pred_class = out.argmax().item()
    model.zero_grad()
    out[0, pred_class].backward()

    grad, act = gradients[0], activations[0]
    weights = grad.mean(dim=[2,3], keepdim=True)
    cam = (weights * act).sum(dim=1).squeeze().cpu().numpy()
    cam = np.maximum(cam,0)
    cam = cv2.resize(cam, (224,224))
    cam = cam / (cam.max() + 1e-8)

    h1.remove(); h2.remove()
    return cam, pred_class

# ============================================
# GRAD-CAM VISUALIZATION (1 sample/class)
# ============================================
plt.figure(figsize=(12, 6))
shown_classes = set()
count = 1

for i in range(len(test_data)):
    img, label = test_data[i]
    if label not in shown_classes:
        cam, pc = grad_cam(model_cls, img, model_cls.features[-1])
        img_np = img.permute(1,2,0).cpu().numpy()
        plt.subplot(1, len(classes), count)
        plt.imshow(img_np)
        plt.imshow(cam, cmap='jet', alpha=0.5)
        plt.title(f"GT:{classes[label]}\nPred:{classes[pc]}")
        plt.axis('off')
        shown_classes.add(label)
        count += 1
    if len(shown_classes) == len(classes):
        break

plt.suptitle("Grad-CAM (1 sample per class)")
plt.tight_layout()
plt.show()

