import os
import torch
import numpy as np
from torchvision import transforms, models
from PIL import Image
from pytorch_grad_cam import GradCAM
from pytorch_grad_cam.utils.model_targets import ClassifierOutputTarget

# ============================
# PATH CONFIG
# ============================
MODEL_PATH = "/content/drive/MyDrive/brisc2025/cls_best.pth"  # classification model
TEST_DIR   = "/content/drive/MyDrive/brisc2025/classification_task/test"
SAVE_CAM_DIR = "/content/drive/MyDrive/brisc2025/gradcam_masks"

os.makedirs(SAVE_CAM_DIR, exist_ok=True)
device = "cuda" if torch.cuda.is_available() else "cpu"

# ============================
# Load Model
# ============================
num_classes = 4  # adjust according to your dataset
model = models.efficientnet_b3(weights=None)
model.classifier[1] = torch.nn.Linear(model.classifier[1].in_features, num_classes)
model.load_state_dict(torch.load(MODEL_PATH, map_location=device))
model.to(device)
model.eval()

# Target layer for Grad-CAM
target_layer = model.features[-1]

# ============================
# Transform
# ============================
transform = transforms.Compose([
    transforms.Resize((224,224)),
    transforms.ToTensor(),
    transforms.Normalize([0.485, 0.456, 0.406],
                         [0.229, 0.224, 0.225])
])

# ============================
# Grad-CAM generator
# ============================
cam_generator = GradCAM(model=model, target_layers=[target_layer], use_cuda=(device=="cuda"))

# ============================
# Loop through test images
# ============================
valid_exts = (".png", ".jpg", ".jpeg")
all_images = sorted([f for f in os.listdir(TEST_DIR) if f.endswith(valid_exts)])
print("Total test images found:", len(all_images))

for img_name in all_images:
    img_path = os.path.join(TEST_DIR, img_name)
    img = Image.open(img_path).convert("RGB")
    input_tensor = transform(img).unsqueeze(0).to(device)

    # Prediction
    output = model(input_tensor)
    pred_class = output.argmax(dim=1).item()

    # Generate Grad-CAM
    grayscale_cam = cam_generator(input_tensor=input_tensor,
                                  targets=[ClassifierOutputTarget(pred_class)])
    grayscale_cam = grayscale_cam[0]

    # Save CAM as .npy
    base = os.path.splitext(img_name)[0]
    np.save(os.path.join(SAVE_CAM_DIR, base + "_cam.npy"), grayscale_cam)

print("✅ All Grad-CAM masks saved in:", SAVE_CAM_DIR)

